  "implementation": "def solve(case):
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not nodes or required_symbols is None:
        raise ValueError('Invalid case: missing nodes or required_symbols')

    node_map = {node['id']: node for node in nodes}
    children_map = {}
    for node in nodes:
        pid = node.get('parent')
        if pid is not None:
            children_map.setdefault(pid, []).append(node['id'])

    root_id = None
    for node in nodes:
        if node.get('parent') is None:
            root_id = node['id']
            break

    retained = set(node_map.keys())
    symbol_count = {}
    for node in nodes:
        sym = node['symbol']
        symbol_count[sym] = symbol_count.get(sym, 0) + 1

    # Order: depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_order = []

    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if nid == root_id or not node['removable']:
            continue
        # Check required symbols: if this node's symbol is required and its count would drop to 0, cannot remove
        sym = node['symbol']
        if sym in required_symbols and symbol_count[sym] <= 1:
            continue
        # Check children: must have no retained children
        child_ids = children_map.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        # Remove node
        retained.remove(nid)
        symbol_count[sym] -= 1
        removed_order.append(nid)

    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_sorted}
